#include "ResourceVaultBridge.h"
#include <mach-o/getsect.h>
#include <mach-o/ldsyms.h>
#include <stdint.h>
#include <stddef.h>

static volatile const uint8_t rv_share_a[32] = { 0xed, 0x7d, 0x07, 0x3f, 0x61, 0x71, 0x97, 0x0d, 0x0a, 0x2e, 0xfd, 0xa8, 0xaf, 0x6a, 0x79, 0xa9, 0x60, 0xc5, 0xfc, 0x0d, 0xc3, 0xc8, 0x8f, 0xd4, 0x80, 0xde, 0xbe, 0xb1, 0x34, 0xf1, 0x52, 0x06 };
static volatile const uint8_t rv_share_b[32] = { 0x58, 0x60, 0x6c, 0x87, 0x37, 0xea, 0x7d, 0x2e, 0x15, 0xd7, 0x0d, 0x2a, 0x15, 0x93, 0xf3, 0x21, 0x4d, 0x66, 0xcd, 0x57, 0x47, 0xe1, 0x62, 0xd2, 0x1b, 0xc2, 0x01, 0xc0, 0xab, 0xf7, 0x9d, 0x77 };
static volatile const uint8_t rv_share_c[32] = { 0x8f, 0xdc, 0x2b, 0xa9, 0xea, 0x2e, 0xc1, 0x99, 0x68, 0x0a, 0x6a, 0x37, 0xa6, 0x11, 0xf3, 0x77, 0x22, 0xdc, 0x5d, 0xf1, 0xc5, 0x11, 0xd1, 0x08, 0x22, 0xb8, 0x32, 0xa5, 0x07, 0x5a, 0xb3, 0x0c };

const uint8_t *resource_vault_section(size_t *size) {
    if (size) *size = 0;
    unsigned long section_size = 0;
    const struct mach_header_64 *header = (const struct mach_header_64 *)&_mh_execute_header;
    const uint8_t *bytes = getsectiondata(header, "__DATA", "__rv3105", &section_size);
    if (!bytes || section_size == 0) return NULL;
    if (size) *size = (size_t)section_size;
    return bytes;
}

__attribute__((noinline))
void resource_vault_copy_key(uint8_t out_key[32]) {
    if (!out_key) return;
    for (size_t i = 0; i < 32; i++) out_key[i] = (uint8_t)(rv_share_a[i] ^ rv_share_b[i] ^ rv_share_c[i]);
}
